import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target_positions = inputs["target_positions"]
    position_events = inputs["position_events"]

    # 1. Deduplicate events delivered more than once (same batch_seq == same event)
    events = position_events.drop_duplicates(subset=["batch_seq"], keep="first")

    # Build current state dict from target_positions: key -> (qty, price, row_version)
    state = {}
    target_had_row = {}
    for row in target_positions.itertuples(index=False):
        key = (row.account_id, row.symbol)
        state[key] = (row.qty, row.price, row.row_version)
        target_had_row[key] = row.row_version

    # Group events by key
    events_by_key = {}
    for row in events.itertuples(index=False):
        key = (row.account_id, row.symbol)
        events_by_key.setdefault(key, []).append(row)

    all_keys = set(state.keys()) | set(events_by_key.keys())

    new_positions_rows = []
    closed_positions_rows = []

    for key in all_keys:
        account_id, symbol = key
        current = state.get(key, None)
        guard_version = target_had_row.get(key, None)

        ev_list = events_by_key.get(key, [])

        # 2. Replay guard
        if guard_version is not None:
            ev_list = [e for e in ev_list if e.row_version > guard_version]

        # 3. Order by row_version, batch_seq
        ev_list = sorted(ev_list, key=lambda e: (e.row_version, e.batch_seq))

        last_removed_version = None

        for ev in ev_list:
            op = ev.op
            if op == 'D':
                if current is not None:
                    current = None
                    last_removed_version = ev.row_version
                # else: does nothing
            elif op in ('I', 'U'):
                ev_qty = ev.qty
                ev_price = ev.price
                is_zero_qty = (ev_qty == 0)
                if is_zero_qty:
                    if current is not None:
                        current = None
                        last_removed_version = ev.row_version
                    # else: does nothing
                else:
                    if current is not None:
                        new_qty = ev_qty
                        if op == 'U' and pd.isna(ev_price):
                            new_price = current[1]
                        else:
                            new_price = ev_price
                        current = (new_qty, new_price, ev.row_version)
                    else:
                        current = (ev_qty, ev_price, ev.row_version)
            # else: unknown op, ignore

        if current is not None:
            qty_val, price_val, rv = current
            new_positions_rows.append({
                "account_id": account_id,
                "symbol": symbol,
                "qty": qty_val,
                "price": price_val,
                "row_version": rv,
            })
        else:
            if last_removed_version is not None:
                closed_positions_rows.append({
                    "account_id": account_id,
                    "symbol": symbol,
                    "closed_version": last_removed_version,
                })

    new_positions = pd.DataFrame(
        new_positions_rows,
        columns=["account_id", "symbol", "qty", "price", "row_version"]
    )
    if not new_positions.empty:
        new_positions["account_id"] = new_positions["account_id"].astype("int64")
        new_positions["qty"] = new_positions["qty"].astype("int64")
        new_positions["price"] = new_positions["price"].astype("float64")
        new_positions["row_version"] = new_positions["row_version"].astype("int64")
    else:
        new_positions = pd.DataFrame({
            "account_id": pd.Series(dtype="int64"),
            "symbol": pd.Series(dtype="object"),
            "qty": pd.Series(dtype="int64"),
            "price": pd.Series(dtype="float64"),
            "row_version": pd.Series(dtype="int64"),
        })

    closed_positions = pd.DataFrame(
        closed_positions_rows,
        columns=["account_id", "symbol", "closed_version"]
    )
    if not closed_positions.empty:
        closed_positions["account_id"] = closed_positions["account_id"].astype("int64")
        closed_positions["closed_version"] = closed_positions["closed_version"].astype("int64")
    else:
        closed_positions = pd.DataFrame({
            "account_id": pd.Series(dtype="int64"),
            "symbol": pd.Series(dtype="object"),
            "closed_version": pd.Series(dtype="int64"),
        })

    return {
        "new_positions": new_positions,
        "closed_positions": closed_positions,
    }
